'use strict';
let familyStorageKey=KEY;
const familyPersist=persist;persist=function(){if(familyStorageKey===KEY){familyPersist();return}upgradeSave();try{localStorage.setItem(familyStorageKey,JSON.stringify(data))}catch{notify('未能儲存進度，請檢查瀏覽器儲存空間。')}};
function activateFamily(profile){familyStorageKey=profile.familyId==='demo'?KEY:`starlight-family-${profile.familyId}`;try{data=JSON.parse(localStorage.getItem(familyStorageKey))||initial()}catch{data=initial()}if(profile.familyId!=='demo'){data.nickname=profile.nickname;data.grade=profile.grade;data.birthYear=profile.birthYear;data.parentName=profile.parentName}data.hero=0;migrateCrystalCurrency(data);upgradeSave();chosen=0;persist()}
const registrationLogin=login;login=function(){return registrationLogin().replace('<footer class="gate-footer">','<div class="register-invite"><span>第一次嚟到星光世界？</span><button class="nav-pill" data-register="open">'+icon('shield')+' 註冊家長帳戶 · Register</button><small>由家長建立家庭，並設定小朋友嘅登入資料。</small></div><footer class="gate-footer">')};
function registrationPage(){const field=(name,label,type='text',extra='')=>`<label class="field" for="reg-${name}">${label}</label><input class="input" id="reg-${name}" name="${name}" type="${type}" ${extra} required>`;return `<main class="screen registration-screen">${backdrop()}<header class="topbar">${brand()}<button class="nav-pill" data-register="back">返回登入</button></header><section class="registration-wrap"><div class="gate-heading"><p class="section-kicker">A NEW FAMILY CHAPTER</p><div class="gate-ornament">✦</div><h1>成為星光守護者</h1><p>由家長填好資料，為小朋友開啟第一章。</p></div><form class="paper registration-card" id="register-form"><div class="registration-step"><span>01</span><h2>公會長的印記<small>家長帳戶</small></h2></div>${field('parentName','家長稱呼','text','maxlength="60" autocomplete="nickname"')}${field('username','家長登入名稱','text','pattern="[A-Za-z0-9_-]{3,32}" minlength="3" maxlength="32" autocomplete="username"')}<p class="subtle">3–32 個英文字母、數字、_ 或 -</p><div class="form-grid"><div>${field('password','家長密碼','password','minlength="8" maxlength="128" autocomplete="new-password"')}</div><div>${field('confirmPassword','再次輸入家長密碼','password','minlength="8" maxlength="128" autocomplete="new-password"')}</div></div><div class="registration-step"><span>02</span><h2>勇者的冒險手冊<small>由家長設定小朋友資料</small></h2></div>${field('nickname','小朋友暱稱','text','maxlength="30"')}<div class="form-grid"><div><label class="field" for="reg-grade">目前年級</label><select class="input" id="reg-grade" name="grade" required><option value="">請選擇</option>${[1,2,3,4,5,6].map(v=>`<option value="${v}">小學 ${v} 年級</option>`).join('')}</select></div><div>${field('birthYear','出生年份','number',`min="2000" max="${new Date().getFullYear()}"`)}</div></div>${field('childUsername','小朋友登入名稱','text','pattern="[A-Za-z0-9_-]{3,32}" minlength="3" maxlength="32" autocomplete="off"')}<div class="form-grid"><div>${field('childPassword','小朋友密碼','password','minlength="8" maxlength="128" autocomplete="new-password"')}</div><div>${field('confirmChildPassword','再次輸入小朋友密碼','password','minlength="8" maxlength="128" autocomplete="new-password"')}</div></div><p class="subtle">兩個帳戶名稱須不同；密碼最少 8 個字元。小朋友首次登入再揀自己嘅勇者角色。</p><p class="demo-note">本機測試版：帳戶保存在這部電腦；學習進度按家庭分開，保留於目前瀏覽器，暫不支援跨裝置同步。</p><p class="error" id="register-error" role="alert"></p><button class="primary gold" type="submit">建立家庭，開啟冒險 ${icon('arrow')}</button></form></section></main>`}
const registrationRender=render;render=function(){if(page!=='register'){registrationRender();return}clearInterval(roomInterval);$('.overlay')?.remove();$('#app').innerHTML=registrationPage()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-register]');if(b){role='parent';go(b.dataset.register==='open'?'register':'login')}});
document.addEventListener('submit',async e=>{if(e.target.id!=='register-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,b=Object.fromEntries(new FormData(form));const error=$('#register-error');if(b.password!==b.confirmPassword||b.childPassword!==b.confirmChildPassword){error.textContent='兩次輸入嘅密碼唔一致，請再確認。';return}const button=form.querySelector('[type=submit]');button.disabled=true;error.textContent='';try{b.grade=Number(b.grade);b.birthYear=Number(b.birthYear);delete b.confirmPassword;delete b.confirmChildPassword;await localAPI('/api/register',{method:'POST',body:JSON.stringify(b)});role='parent';go('login');$('#username').value=b.username;notify('家庭帳戶已建立！請用家長帳戶登入。')}catch(err){error.textContent=err.message;button.disabled=false}},true);
render();
